/** ICompta Business : plan de comptes paramétrable, propositions d'écritures issues des événements réels, cycle brouillon → à valider → validée/rejetée, écritures IMMUABLES et CHAÎNÉES (hachage), contrepassation/correction, grand livre, balance, comptes tiers, clôture de période scellée.
 *  Anti-falsification : aucune suppression ni modification d'une écriture validée ; numérotation continue sans trou ; chaîne de hachage vérifiable ; scellé à la clôture ; séparation des rôles ; tout est journalisé. Aucun taux, compte ou règle fiscale n'est inventé. */
import { createHash } from "node:crypto";
import { JOURNALS, KIND_LABEL, STATUS_LABEL, balanceOf, canValidate, canonLines, checkLines, entryNumber, isCode, isJournal, periodOf, periodsOfYear, swap, validDay, validPeriod, type Line, type Status } from "../../../src/domain/icompta";
import { approvalStep, requiredApprovals, type Approval, type ApprovalRule } from "../../../src/domain/icompta-pro";
import type { ReportData } from "../../../src/domain/exports";
import { needFeature } from "./articles";
import { MIN, aud, iso, mine, ms, parse, rkey } from "./crm";
import { roleKind } from "./fin-rules";
import { names } from "./inventory";
import { HttpError, need, needModule, type BatchOp, type Ctx, type Row, type Store } from "./store";

/** Points d'extension d'ICompta Pro (enregistrés par icompta-pro.ts) : le cœur Business ne dépend pas du Pro. */
export type ProState = { approval: ApprovalRule; analyticRequired: boolean; dims: { act: Set<string>; proj: Set<string> } };
export const hooks: { pro?: (store: Store, ctx: Ctx) => Promise<ProState | null>; controls?: (store: Store, ctx: Ctx, key: string) => Promise<Control[]>; proposals?: (store: Store, ctx: Ctx, helpers: { act: Set<string>; taken: Set<string>; closed: Set<string> }) => Promise<Prop[]> } = {};
export const sha = (s: string) => createHash("sha1").update(s).digest("hex");
export const h256 = (s: string) => createHash("sha256").update(s).digest("hex");
export const GENESIS = "GENESIS";
export const today = () => new Date().toISOString().slice(0, 10);
export const text = (v: unknown, n: number) => String(v ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, n);
export const gate = async (store: Store, ctx: Ctx) => { needModule(ctx, "accounting"); await needFeature(store, ctx, "icompta"); if (!ctx.shopId) throw new HttpError(400, "Choisissez une boutique : la comptabilité est tenue par boutique"); };
export const isMgr = (ctx: Ctx) => roleKind(ctx) !== "other";
export const mgr = async (store: Store, ctx: Ctx) => { await gate(store, ctx); if (!isMgr(ctx)) throw new HttpError(403, "Réservé au propriétaire et aux gérants"); };

// ------------------------------------------------------------------ plan de comptes et paramétrage
export type Cfg = { pro?: Record<string, any>; categories: Record<string, string>; methods: { cash?: string; transfer?: string; mobile?: string; other?: string }; deferredPayable: string; cashMoveIn: string; cashMoveOut: string };
const EMPTY_CFG: Cfg = { categories: {}, methods: {}, deferredPayable: "", cashMoveIn: "", cashMoveOut: "" };
const accId = (ctx: Ctx, code: string) => `ac${sha(`${ctx.tenantId}|${ctx.shopId}|acct|${code}`).slice(0, 30)}`;
export async function accountsOf(store: Store, ctx: Ctx): Promise<Row[]> {
  const rows = (await store.scan("acct_accounts", MIN(ctx), { maxRows: 5000 })).rows; return rows.sort((a, b) => (String(a.code) < String(b.code) ? -1 : String(a.code) > String(b.code) ? 1 : 0));
}
export const activeSet = (rows: Row[]) => new Set(rows.filter((r) => r.active !== false).map((r) => String(r.code)));
export const cfgId = (ctx: Ctx) => `acfg${sha(`${ctx.tenantId}|${ctx.shopId}|cfg`).slice(0, 28)}`;
export async function cfgOf(store: Store, ctx: Ctx): Promise<Cfg> { const r = await store.get("acct_config", cfgId(ctx)); return { ...EMPTY_CFG, ...(r && mine(ctx, r) ? parse<Partial<Cfg>>(r.data, {}) : {}) }; }
export const REVIEW = "Paramétrage à confirmer par un expert-comptable : l'application ne présume d'aucun compte, taux ou règle fiscale.";

async function usedCodes(store: Store, ctx: Ctx, plan: Set<string>) {
  const m = new Map<string, { code: string; entries: number; debit: number; credit: number }>(); for (const r of await legacyRows(store, ctx)) { const c = String(r.account); const e = m.get(c) ?? { code: c, entries: 0, debit: 0, credit: 0 }; e.entries++; e.debit += Number(r.debit ?? 0); e.credit += Number(r.credit ?? 0); m.set(c, e); }
  return [...m.values()].sort((a, b) => (a.code < b.code ? -1 : 1)).map((e) => ({ ...e, inPlan: plan.has(e.code) }));
}
export async function accounts(store: Store, ctx: Ctx) {
  await gate(store, ctx); const who = await names(store, ctx); const rows = await accountsOf(store, ctx); const plan = new Set(rows.map((r) => String(r.code)));
  return { accounts: rows.map((a) => ({ id: a.$id, code: String(a.code), label: String(a.label), active: a.active !== false, confirmed: !!a.confirmedBy, confirmedBy: who.get(String(a.confirmedBy)) ?? "", confirmedAt: iso(a.confirmedAt) })), used: await usedCodes(store, ctx, plan), journals: JOURNALS, canEdit: isMgr(ctx), empty: rows.length === 0,
    note: `Le plan de comptes est VIDE tant que vous ne le renseignez pas : l'application ne présume d'aucun numéro. Importez le plan fourni par votre expert-comptable (SYSCOHADA révisé), ou ajoutez les comptes un par un. « Codes utilisés par l'application » liste les numéros réellement employés par les écritures automatiques (ventes, achats, paiements) : ce sont des choix techniques de l'application, à faire valider ou à rapprocher de votre plan. ${REVIEW}` };
}
export async function accountImport(store: Store, ctx: Ctx, b: { text?: string }) {
  await mgr(store, ctx); const lines = String(b.text ?? "").split(/\r?\n/).map((l) => l.trim()).filter(Boolean); if (!lines.length) throw new HttpError(400, "Collez une ligne par compte : numéro;libellé"); if (lines.length > 1000) throw new HttpError(400, "1000 lignes au plus par import");
  const have = new Set((await accountsOf(store, ctx)).map((r) => String(r.code))); const created: string[] = [], skipped: { line: string; why: string }[] = []; const ops: BatchOp[] = [];
  for (const l of lines) { const m = l.match(/^(\d{2,8})\s*[;\t,:-]\s*(.+)$/); if (!m) { skipped.push({ line: l.slice(0, 60), why: "format attendu : numéro;libellé" }); continue; } const code = m[1]!; const label = text(m[2], 120); if (label.length < 2) { skipped.push({ line: l.slice(0, 60), why: "libellé manquant" }); continue; } if (!isCode(code)) { skipped.push({ line: l.slice(0, 60), why: "numéro invalide" }); continue; } if (have.has(code)) { skipped.push({ line: l.slice(0, 60), why: "déjà au plan" }); continue; } have.add(code); created.push(code); ops.push({ kind: "create", table: "acct_accounts", id: accId(ctx, code), tenantId: ctx.tenantId, data: { ...MIN(ctx), code, label, active: true, seeded: false, createdBy: ctx.userId } }); }
  for (let i = 0; i < ops.length; i += 80) await store.batch(ops.slice(i, i + 80)); if (created.length) await store.create("audit_log", crypto.randomUUID().replace(/-/g, "").slice(0, 30), ctx.tenantId, { ...MIN(ctx), userId: ctx.userId, action: "icompta.account.import", detail: `${created.length} compte(s) importé(s)` }); return { created: created.length, skipped };
}
export async function accountSave(store: Store, ctx: Ctx, b: { code?: string; label?: string; active?: boolean; confirm?: boolean }) {
  await mgr(store, ctx); const code = String(b.code ?? ""); if (!isCode(code)) throw new HttpError(400, "Numéro de compte invalide (2 à 8 chiffres, ne commence pas par 0)"); const rows = await accountsOf(store, ctx); const cur = rows.find((r) => r.code === code); const label = b.label !== undefined ? text(b.label, 120) : cur ? String(cur.label) : ""; if (label.length < 2) throw new HttpError(400, "Libellé obligatoire (2 caractères au moins)");
  if (b.confirm === true && roleKind(ctx) !== "owner") throw new HttpError(403, "Seul le propriétaire déclare un compte « confirmé par un professionnel »");
  if (!cur) { await store.batch([{ kind: "create", table: "acct_accounts", id: accId(ctx, code), tenantId: ctx.tenantId, data: { ...MIN(ctx), code, label, active: b.active !== false, seeded: false, createdBy: ctx.userId, ...(b.confirm === true ? { confirmedBy: ctx.userId, confirmedAt: new Date().toISOString() } : {}) } }, aud(ctx, "icompta.account.create", `${code} ${label}`)]); return { code, created: true }; }
  const data: Record<string, unknown> = { label }; if (b.active !== undefined) data.active = b.active === true; if (b.confirm === true) { data.confirmedBy = ctx.userId; data.confirmedAt = new Date().toISOString(); }
  await store.batch([{ kind: "update", table: "acct_accounts", id: cur.$id, data }, aud(ctx, "icompta.account.update", JSON.stringify({ code, before: { label: cur.label, active: cur.active !== false }, after: data }))]); return { code, created: false };
}
export async function config(store: Store, ctx: Ctx) {
  await gate(store, ctx); const cfg = await cfgOf(store, ctx); const cats = new Set<string>(); for (const e of (await store.scan("expenses", { ...MIN(ctx), status: "approved" }, { maxRows: 20_000 })).rows) cats.add(String(e.category));
  return { config: cfg, categories: [...cats].sort(), unmappedCategories: [...cats].filter((c) => !cfg.categories[c]), canEdit: isMgr(ctx), note: `${REVIEW} Chaque événement dépend d'une correspondance que vous définissez : tant qu'elle manque, la proposition correspondante reste bloquée.` };
}
export async function configSave(store: Store, ctx: Ctx, b: { config?: Partial<Cfg> }) {
  await mgr(store, ctx); const act = activeSet(await accountsOf(store, ctx)); const c = b.config ?? {}; const chk = (code: unknown, label: string): string => { const v = String(code ?? ""); if (!v) return ""; if (!isCode(v) || !act.has(v)) throw new HttpError(400, `${label} : le compte ${v} n'existe pas ou est désactivé dans le plan de comptes`); return v; };
  const next: Cfg = { categories: {}, methods: { cash: chk(c.methods?.cash, "Espèces") || undefined, transfer: chk(c.methods?.transfer, "Banque / virement") || undefined, mobile: chk(c.methods?.mobile, "Mobile money") || undefined, other: chk(c.methods?.other, "Autre moyen") || undefined }, deferredPayable: chk(c.deferredPayable, "Dettes à payer"), cashMoveIn: chk(c.cashMoveIn, "Apport de caisse"), cashMoveOut: chk(c.cashMoveOut, "Retrait de caisse") };
  for (const [k, v] of Object.entries(c.categories ?? {})) { const code = chk(v, `Catégorie « ${k} »`); if (code) next.categories[text(k, 40)] = code; }
  const id = cfgId(ctx); const ex = await store.get("acct_config", id); const pro = (await cfgOf(store, ctx)).pro; if (pro) next.pro = pro; await store.batch([ex ? { kind: "update", table: "acct_config", id, data: { data: JSON.stringify(next), updatedBy: ctx.userId } } : { kind: "create", table: "acct_config", id, tenantId: ctx.tenantId, data: { ...MIN(ctx), data: JSON.stringify(next), updatedBy: ctx.userId } }, aud(ctx, "icompta.config", JSON.stringify({ before: ex?.data ?? null, after: next }))]); return { config: next };
}

// ------------------------------------------------------------------ périodes
export const perId = (ctx: Ctx, key: string) => `ap${sha(`${ctx.tenantId}|${ctx.shopId}|per|${key}`).slice(0, 30)}`;
export async function periodRows(store: Store, ctx: Ctx): Promise<Map<string, Row>> { return new Map((await store.scan("acct_periods", MIN(ctx), { maxRows: 500 })).rows.map((r) => [String(r.key), r])); }
export const isClosed = async (store: Store, ctx: Ctx, key: string) => (await store.get("acct_periods", perId(ctx, key)))?.status === "closed";

// ------------------------------------------------------------------ lecture des écritures
export type Ent = { approvals: Approval[]; level: number; id: string; seq: number | null; number: string; journal: string; date: string; period: string; label: string; lines: Line[]; total: number; status: Status; kind: string; originRef: string; sourceKey: string; pieces: Piece[]; createdBy: string; validatedBy: string; validatedAt: string; rejectedBy: string; rejectReason: string; prevHash: string; hash: string; reversalOf: string; reversedBy: string; correctionOf: string; note: string; selfValidated: boolean; at: string };
const entOf = (r: Row): Ent => ({ approvals: parse<Approval[]>(r.approvals, []), level: Number(r.level ?? 0), id: r.$id, seq: r.seq === null || r.seq === undefined || r.seq === "" ? null : Number(r.seq), number: String(r.number ?? ""), journal: String(r.journal), date: String(r.date), period: String(r.period), label: String(r.label ?? ""), lines: parse<Line[]>(r.lines, []), total: Number(r.total ?? 0), status: String(r.status) as Status, kind: String(r.kind ?? "manual"), originRef: String(r.originRef ?? ""), sourceKey: String(r.sourceKey ?? ""), pieces: parse<Piece[]>(r.pieces, []), createdBy: String(r.createdBy ?? ""), validatedBy: String(r.validatedBy ?? ""), validatedAt: iso(r.validatedAt), rejectedBy: String(r.rejectedBy ?? ""), rejectReason: String(r.rejectReason ?? ""), prevHash: String(r.prevHash ?? ""), hash: String(r.hash ?? ""), reversalOf: String(r.reversalOf ?? ""), reversedBy: String(r.reversedBy ?? ""), correctionOf: String(r.correctionOf ?? ""), note: String(r.note ?? ""), selfValidated: r.selfValidated === true, at: iso(r.$createdAt) });
export async function entriesAll(store: Store, ctx: Ctx): Promise<Ent[]> { return (await store.scan("acct_entries", MIN(ctx), { maxRows: 50_000 })).rows.map(entOf); }
export const hashOf = (e: Pick<Ent, "seq" | "number" | "journal" | "date" | "label" | "lines" | "kind" | "originRef" | "pieces" | "createdBy" | "validatedBy" | "validatedAt" | "reversalOf" | "correctionOf"> & { approvals?: Approval[] }, prev: string): string => h256([prev, e.seq, e.number, e.journal, e.date, e.label, canonLines(e.lines), e.kind, e.originRef, JSON.stringify(e.pieces), e.createdBy, e.validatedBy, e.validatedAt, e.reversalOf, e.correctionOf, ...(e.approvals?.length ? [JSON.stringify(e.approvals)] : [])].join("\u001f"));

export async function legacyRows(store: Store, ctx: Ctx, from?: string, to?: string): Promise<Row[]> { return (await store.scan("journal_entries", MIN(ctx), { ...(from || to ? { range: { field: "date", ...(from ? { from: `${from}T00:00:00.000Z` } : {}), ...(to ? { to: `${to}T23:59:59.999Z` } : {}) } } : {}), maxRows: 100_000 })).rows; }
export const dayOfRow = (r: Row) => (iso(r.date) || String(r.date ?? "")).slice(0, 10);

// ------------------------------------------------------------------ propositions (événements réels sans écriture)
export type Piece = { ref: string; label?: string; file?: string; sha256?: string; size?: number; mime?: string };
export type Prop = { key: string; kind: string; date: string; label: string; amount: number; origin: string; lines: Line[]; journal: string; pieces: { ref: string }[]; blocked: string; period: string; closed: boolean };
async function proposals(store: Store, ctx: Ctx): Promise<Prop[]> {
  const cfg = await cfgOf(store, ctx); const act = activeSet(await accountsOf(store, ctx)); const taken = new Set((await entriesAll(store, ctx)).filter((e) => e.status !== "rejected" && e.sourceKey).map((e) => e.sourceKey)); const closed = new Set([...(await periodRows(store, ctx)).values()].filter((r) => r.status === "closed").map((r) => String(r.key))); const out: Prop[] = [];
  const moneyOf = (m: string): { code: string; err: string } => { const code = (cfg.methods as Record<string, string | undefined>)[m] ?? ""; if (!code) return { code: "", err: `Compte du moyen de règlement « ${m === "mobile" ? "mobile money" : m === "other" ? "autre" : m} » non paramétré` }; if (!act.has(code)) return { code: "", err: `Le compte ${code} n'existe pas ou est désactivé` }; return { code, err: "" }; };
  const jr = (code: string) => (code && code === cfg.methods.cash ? "CA" : code && code === cfg.methods.transfer ? "BQ" : "OD");
  const push = (key: string, kind: string, date: string, label: string, amount: number, origin: string, debit: string, credit: string, errs: string[], journal: string, piece: string) => { if (taken.has(sha(key))) return; const blocked = errs.find(Boolean) ?? ""; const lines: Line[] = !blocked && debit && credit ? [{ account: debit, debit: amount, credit: 0 }, { account: credit, debit: 0, credit: amount }] : []; out.push({ key, kind, date, label, amount, origin, lines, journal, pieces: piece ? [{ ref: piece }] : [], blocked, period: periodOf(date), closed: closed.has(periodOf(date)) }); };
  const catOf = (c: string): { code: string; err: string } => { const code = cfg.categories[c] ?? ""; if (!code) return { code: "", err: `Compte de charge non paramétré pour la catégorie « ${c} »` }; if (!act.has(code)) return { code: "", err: `Le compte ${code} n'existe pas ou est désactivé` }; return { code, err: "" }; };
  const exps = (await store.scan("expenses", { ...MIN(ctx), status: "approved" }, { maxRows: 20_000 })).rows; const expById = new Map(exps.map((e) => [e.$id, e]));
  for (const e of exps) { const date = String(e.spentOn).slice(0, 10); const amount = Number(e.amount); const cat = catOf(String(e.category)); const label = `Dépense ${e.number} — ${String(e.label)}`.slice(0, 200);
    if (String(e.payMode ?? "immediate") === "deferred") { const dp = cfg.deferredPayable ? (act.has(cfg.deferredPayable) ? "" : `Le compte ${cfg.deferredPayable} n'existe pas ou est désactivé`) : "Compte des dettes à payer non paramétré"; push(`exp-d:${e.$id}`, "expense", date, `${label} (à payer)`, amount, `expense:${e.number}`, cat.code, cfg.deferredPayable, [cat.err, dp], "AC", String(e.number)); }
    else { const mo = moneyOf(EXP_METHOD[String(e.method)] ?? "other"); push(`exp:${e.$id}`, "expense", date, label, amount, `expense:${e.number}`, cat.code, mo.code, [cat.err, mo.err], jr(mo.code), String(e.number)); } }
  for (const p of (await store.scan("expense_payments", MIN(ctx), { maxRows: 20_000 })).rows) { const e = expById.get(String(p.expenseId)); const mo = moneyOf(EXP_METHOD[String(p.method)] ?? "other"); const dp = cfg.deferredPayable ? (act.has(cfg.deferredPayable) ? "" : `Le compte ${cfg.deferredPayable} n'existe pas ou est désactivé`) : "Compte des dettes à payer non paramétré"; push(`exp-p:${p.$id}`, "expense_payment", String(p.paidOn).slice(0, 10), `Paiement de la dépense ${e?.number ?? ""}`.trim(), Number(p.amount), `expense:${String(e?.number ?? p.$id)}`, cfg.deferredPayable, mo.code, [dp, mo.err], jr(mo.code), String(e?.number ?? "")); }
  for (const m of (await store.scan("cash_movements", MIN(ctx), { maxRows: 20_000 })).rows) { if (m.expenseId || m.supplierPaymentId || ["pending", "refused", "rejected", "cancelled"].includes(String(m.status))) continue; const date = iso(m.at).slice(0, 10); if (!date) continue; const inn = m.kind === "in"; const other = inn ? cfg.cashMoveIn : cfg.cashMoveOut; const cashAcc = cfg.methods.cash ?? ""; const err = !cashAcc ? "Compte des espèces (caisse) non paramétré" : !act.has(cashAcc) ? `Le compte ${cashAcc} n'existe pas ou est désactivé` : other ? (act.has(other) ? "" : `Le compte ${other} n'existe pas ou est désactivé`) : `Compte de contrepartie des ${inn ? "apports" : "retraits"} de caisse non paramétré`; push(`cm:${m.$id}`, "cash_move", date, `${inn ? "Apport" : "Retrait"} de caisse — ${String(m.reason ?? "")}`.slice(0, 200), Number(m.amount), `cash:${m.$id}`, inn ? cashAcc : other, inn ? other : cashAcc, [err], "CA", ""); }
  if (hooks.proposals) out.push(...(await hooks.proposals(store, ctx, { act, taken, closed })));
  return out.sort((a, b) => a.date.localeCompare(b.date) || a.key.localeCompare(b.key));
}
const EXP_METHOD: Record<string, string> = { cash: "cash", mobile: "mobile", transfer: "transfer", other: "other" };
export async function proposalList(store: Store, ctx: Ctx) { await gate(store, ctx); const ps = await proposals(store, ctx); return { proposals: ps.slice(0, 500).map((p) => ({ key: p.key, kind: p.kind, date: p.date, label: p.label, amount: p.amount, ready: !p.blocked && !p.closed, blocked: p.blocked || (p.closed ? `Période ${p.period} clôturée` : ""), journal: p.journal, lines: p.lines })), ready: ps.filter((p) => !p.blocked && !p.closed).length, blocked: ps.filter((p) => p.blocked || p.closed).length, note: "Une proposition n'est JAMAIS comptabilisée automatiquement : elle devient un brouillon, puis une écriture à valider par un utilisateur autorisé. Les ventes, achats, factures et paiements sont déjà journalisés par le système et ne sont donc pas proposés une seconde fois." }; }
export async function proposalCreate(store: Store, ctx: Ctx, b: { keys?: unknown }) {
  await gate(store, ctx); const keys = Array.isArray(b.keys) ? [...new Set(b.keys.map(String))].slice(0, 50) : []; if (!keys.length) throw new HttpError(400, "Choisissez au moins une proposition (50 au plus)"); const all = await proposals(store, ctx); const done: string[] = []; const skipped: { key: string; why: string }[] = []; const all2 = await entriesAll(store, ctx);
  for (const k of keys) { const p = all.find((x) => x.key === k); if (!p) { skipped.push({ key: k, why: "déjà traitée ou introuvable" }); continue; } if (p.blocked) { skipped.push({ key: k, why: p.blocked }); continue; } if (p.closed) { skipped.push({ key: k, why: `période ${p.period} clôturée` }); continue; }
    const n = all2.filter((e) => e.sourceKey === sha(k)).length; const id = `ae${sha(`${ctx.tenantId}|${ctx.shopId}|prop|${k}|${n}`).slice(0, 30)}`; const ok = await store.create("acct_entries", id, ctx.tenantId, { ...MIN(ctx), journal: p.journal, date: p.date, period: p.period, label: p.label, lines: JSON.stringify(p.lines), total: p.amount, status: "draft", kind: p.kind === "depreciation" || p.kind === "stock_loss" ? p.kind : "proposal", originRef: p.origin, sourceKey: sha(k), pieces: JSON.stringify(p.pieces), createdBy: ctx.userId, selfValidated: false });
    if (ok) { await store.create("audit_log", crypto.randomUUID().replace(/-/g, "").slice(0, 30), ctx.tenantId, { ...MIN(ctx), userId: ctx.userId, action: "icompta.proposal", detail: `${k} → brouillon ${id}` }); done.push(id); } else skipped.push({ key: k, why: "déjà créée" }); }
  return { created: done.length, ids: done, skipped };
}

// ------------------------------------------------------------------ écritures : cycle de vie
async function legacyHasRef(store: Store, ctx: Ctx, ref: string): Promise<boolean> { return (await store.scan("journal_entries", { ...MIN(ctx), ref }, { maxRows: 1 })).rows.length > 0; }
export async function draftChecks(store: Store, ctx: Ctx, lines: unknown, date: unknown, journal: unknown, kind = "manual") {
  if (!isJournal(journal)) throw new HttpError(400, "Journal inconnu (VE, AC, CA, BQ ou OD)"); const d = validDay(date); if (!d) throw new HttpError(400, "Date invalide (AAAA-MM-JJ)"); if (d > today()) throw new HttpError(400, "La date d'une écriture ne peut pas être dans le futur");
  const c = checkLines(lines, activeSet(await accountsOf(store, ctx))); if (!c.ok) throw new HttpError(400, c.errors.join(" ; ")); const pro = hooks.pro ? await hooks.pro(store, ctx) : null; for (const [i, l] of c.lines.entries()) { if (l.act || l.proj) { if (!pro) throw new HttpError(403, "Les axes analytiques (activité, projet) font partie d'ICompta Pro"); if (l.act && !pro.dims.act.has(l.act)) throw new HttpError(400, `Ligne ${i + 1} : activité « ${l.act} » inconnue ou désactivée`); if (l.proj && !pro.dims.proj.has(l.proj)) throw new HttpError(400, `Ligne ${i + 1} : projet « ${l.proj} » inconnu ou désactivé`); } else if (pro?.analyticRequired && (kind === "manual" || kind === "proposal" || kind === "correction") && /^[67]/.test(l.account)) throw new HttpError(400, `Ligne ${i + 1} : l'activité est obligatoire sur les comptes de charges et de produits (paramétrage ICompta Pro)`); } if (await isClosed(store, ctx, periodOf(d))) throw new HttpError(409, `La période ${periodOf(d)} est clôturée : aucune écriture n'y est possible (passez la correction dans la période ouverte)`); return { d, c };
}
